import{z as i,x as o,o as t,c as p,q as s,j as B,D as e,d as l,s as n,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"机架功率密度","description":"","frontmatter":{"title":"机架功率密度","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rack-power-density.md","filePath":"llm/rack-power-density.md","lastUpdated":1791063341000}'),d={name:"llm/rack-power-density.md"};function D(P,a,C,m,F,T){const r=o("Mermaid");return t(),p("div",null,[a[2]||(a[2]=s('<h1 id="机架功率密度" tabindex="-1">机架功率密度 <a class="header-anchor" href="#机架功率密度" aria-label="Permalink to &quot;机架功率密度&quot;">​</a></h1><div class="epigraph"><p>卡的规格表写的是 TFLOPS；机房允许的是每机架千瓦。两者不一致时，先满的是电，不是算。</p><footer>—— 对照公开的 DGX / HGX 机柜功耗量级与数据中心机架配电；液冷细节下一课</footer></div><p><a href="/llm/dataset-storage-streaming">上一课</a> 假定 GPU 在算。本课写它为什么可能不让你插满：单柜功率密度。缺口是把 <a href="/llm/scale-up-vs-scale-out">Scale-Up 超节点</a> 里提过的「液冷机柜、很高的单柜功率」收成一课账——规划并行网格之前，设施屋顶线已经把卡数上限写死。不编造未出现在厂商文档里的某代精确瓦数；用公开量级与机制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统企业机架按 8–15 kW 设计；一台上一代 8 卡训练服务器就可以接近或超过这个数。NVL72 一类超节点把一柜做到几十张 GPU 加 CPU 加交换机，公开产品形态是液冷、高功率机柜，量级上是「一柜抵过去一排」。若机房仍按风冷列头柜供电，你会买得起卡、接不上电，或接上电却因过载降频——有效 FLOPS 不是规格表。</p><p>功率还随负载变：空闲、训练满 Tensor Core、以及检查点期间的波动不同。配电与 UPS 必须按峰值，否则同步的训练脉冲会在同一毫秒拉高整列电流。问题是：<strong>规划单位从「卡数」换成「可供电的卡数」</strong>，再倒推 DP/TP 网格。</p><p><span class="marginnote">PDU（电源分配单元）就是机房里给每个机架分电的「智能插线板」，UPS 则是断电时顶上来的蓄电池组。两者都按「最大能扛多少千瓦」标定——超了就跳闸，跟家里空气开关一个道理。</span></p><p><span class="marginnote">厂商产品页会给出某代 DGX / GB200 机柜的典型或最大功耗。引用时写明是厂商规格，不是本机房实测。未公开的背板电流与 PSU 内部冗余，不写进容量表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三张表对齐：IT 负载（GPU + CPU + NIC + 存储）、制冷功耗（下一课，风冷经常再加 50% 量级的设施 PUE 故事，液冷更低但不是零）、以及 PDU / 母线容量。可部署卡数 = 供电允许的柜数 × 每柜卡数，再扣冗余（N+1 电源、维修下电）。</p><p><span class="marginnote">数字实例：一台 8 卡训练服务器整机功耗常在 10 kW 上下，而传统机架总共按 8–15 kW 设计——等于「一台机器吃光一个机架」。NVL72 一类一柜上百千瓦（NVL72 类），相当于把过去一整排机架的电塞进一个柜子，旧机房自然接不住。</span></p><p>超节点是单一供电故障域：一柜下电损失 72 卡而不是 8 卡。Scale-Out 侧要用副本与检查点补爆炸半径，见故障课。软件上，调度器必须知道机架功率预算，不能按「空闲槽位」塞满高 TDP 作业导致跳闸。</p>',12)),(t(),B(A,null,{default:e(()=>[n(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22%E5%8A%A0%E9%80%9F%E5%99%A8%E8%A7%84%E6%A0%BC%20FLOPS%22%5D%20--%3E%20WANT%5B%22%E6%83%B3%E8%A6%81%E7%9A%84%E5%8D%A1%E6%95%B0%22%5D%0A%20%20PDU%5B%22%E6%9C%BA%E6%9E%B6%E9%85%8D%E7%94%B5%20kW%22%5D%20--%3E%20CAN%5B%22%E5%8F%AF%E4%BE%9B%E7%94%B5%E5%8D%A1%E6%95%B0%22%5D%0A%20%20WANT%20--%3E%20MIN%5B%22%E5%AE%9E%E9%99%85%E9%83%A8%E7%BD%B2%20%3D%20min%22%5D%0A%20%20CAN%20--%3E%20MIN%0A%20%20MIN%20--%3E%20GRID%5B%22%E5%B9%B6%E8%A1%8C%E7%BD%91%E6%A0%BC%20%2F%20%E4%BD%9C%E4%B8%9A%E6%95%B0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"训练作业的功耗接近峰值且同步，比云上异构 web 负载更「方波」。同一机架混部高功耗训练与突发推理，峰值叠加可能超过按平均值批的电。功率感知调度（推迟启动、错开检查点、限制每柜并发作业）是软件对设施的补偿。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"GPU 功耗与利用率、时钟、精度有关。FP8 Tensor Core 打满时往往比等待 NCCL 时更高；通信墙作业「看起来很忙」但功耗可能低于计算墙。设施不能按通信墙的稳态给训练柜做容量，否则一旦网格改对、算力吃满，就会过载。降频是保护，不是性能特性——step time 会不可预测地变长，像网络尾延迟。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"常见误区：初学者容易以为「规格表 700 W × 卡数」就是实际功耗。实际上功耗随负载在几百瓦到 TDP 之间波动，而训练里成千上万张卡同时打满、同时进入检查点，脉冲是同步的——容量按平均值批，就会在某个毫秒集体越线。")],-1)),(t(),B(A,null,{default:e(()=>[n(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20STEP%5B%22%E8%AE%AD%E7%BB%83%20step%20%E5%BC%80%E5%A7%8B%22%5D%20--%3E%20SYNC%5B%22%E6%89%80%E6%9C%89%20GPU%20%E5%90%8C%E6%AD%A5%E8%BF%9B%E5%85%A5%E8%AE%A1%E7%AE%97%E5%AF%86%E9%9B%86%E6%AE%B5%22%5D%0A%20%20SYNC%20--%3E%20PEAK%5B%22%E6%9C%BA%E6%9F%9C%E5%8A%9F%E7%8E%87%E5%86%B2%E5%90%91%E5%B3%B0%E5%80%BC%20kW%22%5D%0A%20%20PEAK%20--%3E%20CHECK%7B%22%E8%B6%85%E8%BF%87%20PDU%20%2F%20%E6%AF%8D%E7%BA%BF%E5%AE%B9%E9%87%8F%EF%BC%9F%22%7D%0A%20%20CHECK%20--%20%22%E5%90%A6%22%20--%3E%20OK%5B%22%E6%AD%A3%E5%B8%B8%E8%BF%90%E8%A1%8C%EF%BC%8C%E8%BF%9B%E5%85%A5%E4%B8%8B%E4%B8%80%E6%AD%A5%22%5D%0A%20%20CHECK%20--%20%22%E6%98%AF%22%20--%3E%20TRIP%5B%22%E8%B7%B3%E9%97%B8%EF%BC%8C%E6%88%96%E8%A7%A6%E5%8F%91%E9%99%8D%E9%A2%91%E4%BF%9D%E6%8A%A4%22%5D%0A%20%20TRIP%20--%3E%20SLOW%5B%22step%20time%20%E4%B8%8D%E5%8F%AF%E9%A2%84%E6%B5%8B%E5%8F%98%E9%95%BF%22%5D%0A%20%20TRIP%20--%3E%20DOWN%5B%22%E6%95%B4%E6%9F%9C%E4%B8%8B%E7%94%B5%20%3D%20%E4%B8%80%E6%AC%A1%E6%8D%9F%E5%A4%B1%E5%87%A0%E5%8D%81%E5%BC%A0%E5%8D%A1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><a href="/llm/nvlink">NVLink</a> 域把许多 GPU 绑成一台逻辑机器，电上也更像一台：同时拉高。这与分散在许多低功率机架上的 Scale-Out 不同。形态选择包含电力形态，不只是带宽形态。</p><p><span class="marginnote">PUE 把制冷算进总电。液冷把热更直接地交给水，机房 PUE 可变好，但厂级仍要排热。不要用「液冷所以免费加一倍卡」的口号替代 PDU 表。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用桌面 GPU 的 TDP 去乘服务器卡数。不要忽略 CPU、NVSwitch、NIC、光模块——超节点里它们不是零头。不要在合同电力未改之前按产品宣传柜数下单。下一课液冷是功率密度的配套，不是独立的「更环保」选修。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可部署卡数由机架千瓦与峰值负载决定，不是由规格 TFLOPS。</li><li>超节点是高密度供电故障域；网格规划必须先问电。</li><li>训练负载同步且接近峰值，按平均值配电会在算满时跳闸或降频。</li><li>调度需要功率预算，不能只看空闲 GPU。</li><li>出处：厂商公开的机柜功耗规格；数据中心配电与 PUE 常识。</li></ul>',6))])}const h=i(d,[["render",D]]);export{c as __pageData,h as default};
